		public float Update(float error, float dt) {
			if (dt <= 0f)
				return 0f;

			if (!initialized) {
				initialized = true;
				previousError = error;
			}

			integral = Mathf.Clamp(
				integral + error * dt,
				-settings.integralLimit,
				settings.integralLimit);

			float rawDerivative = (error - previousError) / dt;
			float blend = 1f - Mathf.Exp(-settings.derivativeResponse * dt);
			derivative = Mathf.Lerp(derivative, rawDerivative, blend);
			previousError = error;

			return settings.proportional * error
				 + settings.integral * integral
				 + settings.derivative * derivative;
		}
	}

