	public void Recompute(double timeStepsPerSecond) {
		if (recomputing)
			return;

		if (positionPid == null)
			positionPid = new PidSettings();

		recomputing = true;

		try {
			timeStepsPerSecond = Math.Max(1.0, timeStepsPerSecond);
			double timeStep = 1.0 / timeStepsPerSecond;
			RebuildSplineCache();
			flightCache.Clear();
			CacheReachedPathEnd = false;

			if (splineSamples.Count == 0) {
				configurationHash = ComputeConfigurationHash();
				cacheRevision++;
				return;
			}

			bool pathHasTraversal =
				splineSamples.Count >= 2 &&
				splineLength > Mathf.Epsilon;

			Vector3 initialPosition = GetValidPoint(0);
			Quaternion initialRotation = GetIdealPathRotation(initialPosition, 0f);

			SimulationState state = new SimulationState
			{
				position = initialPosition,
				rotation = initialRotation,
				velocity = initialVelocity,
				angularVelocity = Vector3.zero,
				lean = Vector2.zero,
				pathDistance = 0f,
				time = 0.0
