			state.splineTarget =
				startupHoverTime > 0f || !pathHasTraversal
					? initialPosition
					: GetPointAtDistance(
						state.pathDistance + lookAheadDistance);
			AddFlightSample(state);

			Vector3 startupHoverDirection =
				GetTangentAtDistance(0f);

			SimulateHoverPhase(
				ref state,
				GetValidPoint(0),
				startupHoverDirection,
				startupHoverTime,
				timeStep);

			if (pathHasTraversal) {
				PidController pathPidX = new PidController(positionPid);
				PidController pathPidY = new PidController(positionPid);
				PidController pathPidZ = new PidController(positionPid);
				double pathStartTime = state.time;

