						ref state,
						pathPidX,
						pathPidY,
						pathPidZ,
						(float)timeStep);
					AddFlightSample(state);
				}

				CacheReachedPathEnd = HasReachedPathEnd(state);
			} else {
				CacheReachedPathEnd = true;
			}

			if (CacheReachedPathEnd && endingHoverTime > 0f) {
				Vector3 endingAnchor = closedLoop
					? GetValidPoint(0)
					: GetValidPoint(pathPoints.Count - 1);

				Vector3 endingHoverDirection = pathHasTraversal
					? GetTangentAtDistance(splineLength)
					: startupHoverDirection;

