	public void OptimizeLookAheadDistance(double desiredTimeSeconds) {
		desiredTimeSeconds =
			double.IsNaN(desiredTimeSeconds) ||
			double.IsInfinity(desiredTimeSeconds)
				? 0.001
				: Math.Max(0.001, desiredTimeSeconds);
		lookAheadOptimizationDesiredTime = desiredTimeSeconds;
		RebuildSplineCache();

		if (splineSamples.Count < 2 || splineLength <= Mathf.Epsilon) {
			Debug.LogWarning(
				"Look-ahead optimization requires at least two path points.",
				this);
			return;
		}

		float originalLookAhead = lookAheadDistance;
		float minimumLookAhead = Mathf.Max(0.001f, splineLength * 0.0001f);
		float maximumLookAhead = Mathf.Max(minimumLookAhead * 2f, splineLength);
		float bestLookAhead = Mathf.Clamp(
			lookAheadDistance,
			minimumLookAhead,
			maximumLookAhead);

		double previewRate = Math.Max(
			1.0,
			editorPreviewTimeStepsPerSecond);

		double bestDuration;
		double bestError = EvaluateLookAheadCandidate(
			bestLookAhead,
			desiredTimeSeconds,
			previewRate,
			out bestDuration);

		const int coarseTrialCount = 12;
		double logarithmicRange = Math.Log(
			maximumLookAhead / minimumLookAhead);
		double localRatio = Math.Exp(
			logarithmicRange / (coarseTrialCount - 1));

		for (int i = 0; i < coarseTrialCount; i++) {
			float candidate = minimumLookAhead * (float)Math.Exp(
				logarithmicRange * i / (coarseTrialCount - 1));

			double duration;
			double error = EvaluateLookAheadCandidate(
				candidate,
				desiredTimeSeconds,
				previewRate,
				out duration);

			if (error >= bestError)
				continue;

			bestError = error;
			bestDuration = duration;
			bestLookAhead = candidate;
		}

		if (double.IsPositiveInfinity(bestError)) {
			lookAheadDistance = originalLookAhead;
			Recompute();
			Debug.LogWarning(
				"No look-ahead distance completed the path with the current flight settings.",
				this);
			return;
		}

		float lower = Mathf.Max(
			minimumLookAhead,
			bestLookAhead / (float)localRatio);
		float upper = Mathf.Min(
			maximumLookAhead,
			bestLookAhead * (float)localRatio);

		const float inverseGoldenRatio = 0.61803398875f;
		float c = upper - (upper - lower) * inverseGoldenRatio;
		float d = lower + (upper - lower) * inverseGoldenRatio;

		double cDuration;
		double cError = EvaluateLookAheadCandidate(
			c,
			desiredTimeSeconds,
			previewRate,
			out cDuration);

		double dDuration;
		double dError = EvaluateLookAheadCandidate(
			d,
			desiredTimeSeconds,
			previewRate,
			out dDuration);

		for (int i = 0; i < 8; i++) {
			if (cError <= dError) {
				upper = d;
				d = c;
				dError = cError;
				dDuration = cDuration;
				c = upper - (upper - lower) * inverseGoldenRatio;
				cError = EvaluateLookAheadCandidate(
					c,
					desiredTimeSeconds,
					previewRate,
					out cDuration);
			} else {
				lower = c;
				c = d;
				cError = dError;
				cDuration = dDuration;
				d = lower + (upper - lower) * inverseGoldenRatio;
				dError = EvaluateLookAheadCandidate(
					d,
					desiredTimeSeconds,
					previewRate,
					out dDuration);
			}
		}

		if (cError < bestError) {
			bestError = cError;
			bestDuration = cDuration;
			bestLookAhead = c;
		}

		if (dError < bestError) {
			bestError = dError;
			bestDuration = dDuration;
			bestLookAhead = d;
		}

		double playModeRate = Math.Max(
			1.0,
			playModeCacheTimeStepsPerSecond);

		bestError = EvaluateLookAheadCandidate(
			bestLookAhead,
			desiredTimeSeconds,
			playModeRate,
			out bestDuration);

		float refinementStep = Mathf.Max(
			(upper - lower) * 0.25f,
			maximumLookAhead * 0.0025f);

		for (int i = 0; i < 5; i++) {
			float center = bestLookAhead;
			float left = Mathf.Max(
				minimumLookAhead,
				center - refinementStep);
			float right = Mathf.Min(
				maximumLookAhead,
				center + refinementStep);

			double leftDuration;
			double leftError = EvaluateLookAheadCandidate(
				left,
				desiredTimeSeconds,
				playModeRate,
				out leftDuration);

			if (leftError < bestError) {
				bestError = leftError;
				bestDuration = leftDuration;
				bestLookAhead = left;
			}

			double rightDuration;
			double rightError = EvaluateLookAheadCandidate(
				right,
				desiredTimeSeconds,
				playModeRate,
				out rightDuration);

			if (rightError < bestError) {
				bestError = rightError;
				bestDuration = rightDuration;
				bestLookAhead = right;
			}

			refinementStep *= 0.5f;
		}

		lookAheadDistance = bestLookAhead;
		Recompute(playModeRate);
		LastLookAheadOptimizationDuration = CachedDuration;

		if (!Application.isPlaying && selectedPathPointIndex >= 0) {
			ApplySelectedPointPreview();
		} else {
			double requestedTime =
				timeMode == TimeMode.ManualDeterministic
					? manualTime
					: automaticTime;
			ApplyTime(requestedTime, true);
		}
	}

	private double EvaluateLookAheadCandidate(
		float candidate,
		double desiredTimeSeconds,
		double timeStepsPerSecond,
		out double duration) {
		lookAheadDistance = candidate;
		Recompute(timeStepsPerSecond);
		duration = CachedDuration;

		return CacheReachedPathEnd
			? Math.Abs(duration - desiredTimeSeconds)
			: double.PositiveInfinity;
	}

	private bool LoadPregeneratedPlayModeCache() {
		if (pregeneratedPlayModeCache == null ||
			pregeneratedPlayModeCache.Count == 0 ||
			pregeneratedPlayModeConfigurationHash !=
				ComputeConfigurationHash() ||
			!Mathf.Approximately(
				pregeneratedPlayModeTimeStepsPerSecond,
				playModeCacheTimeStepsPerSecond)) {
			return false;
		}

		RebuildSplineCache();
		flightCache.Clear();
		flightCache.AddRange(pregeneratedPlayModeCache);
		configurationHash = pregeneratedPlayModeConfigurationHash;
		CacheReachedPathEnd =
			pregeneratedPlayModeCacheReachedPathEnd;
		cacheRevision++;
		lastAppliedCacheRevision = -1;
		return true;
	}

