	public void SetManualTime(double time) {
		timeMode = TimeMode.ManualDeterministic;
		manualTime = time;

		if (recomputeOnFlightParameterChange &&
			ComputeConfigurationHash() != configurationHash) {
			Recompute();
		}

		ApplyTime(manualTime, true);
	}

	public Vector3 GetPathPoint(int index) {
		return pathPoints[index];
	}

	public void SetPathPoint(int index, Vector3 worldPosition) {
		if (index < 0 || index >= pathPoints.Count)
			return;

		pathPoints[index] = worldPosition;
		Recompute();

		if (!Application.isPlaying && selectedPathPointIndex == index)
			ApplySelectedPointPreview();
	}

	public void SelectPathPointForPreview(int index) {
		selectedPathPointIndex =
			index >= 0 && index < pathPoints.Count ? index : -1;

		if (!Application.isPlaying && selectedPathPointIndex >= 0)
			ApplySelectedPointPreview();
	}

	public void ClearPathPointSelection() {
		selectedPathPointIndex = -1;
		lastAppliedCacheRevision = -1;
	}

	public override void UpdateMotion(ulong t) {
		ApplyTime(t / (double)DVConfig.timeScale, false);
	}

	private void Update() {
		if (timeMode == TimeMode.AutomaticPreview) {
			if (!initialized)
				Initialize();

			EnsureCacheIsCurrent();

			if (flightCache.Count == 0)
				return;

			if (!Application.isPlaying && selectedPathPointIndex >= 0) {
				ApplySelectedPointPreview();
				return;
			}

			if (Application.isPlaying) {
				automaticTime += Time.deltaTime * playbackSpeed;
				ApplyTime(automaticTime, false);
			} else {
				ApplyTime(manualTime, false);
			}
		}
	}

	private void EnsureCacheIsCurrent() {
		if (recomputeOnFlightParameterChange &&
			!recomputing &&
			ComputeConfigurationHash() != configurationHash) {
			Recompute();
		}
	}

